19→// AppendFileEdit appends a single FileEdit record to the session's edit log.
20→// This is an append-only operation -- no read-modify-write cycle.
21→func (s *StateStore) AppendFileEdit(sessionID string, edit agent.FileEdit) error {
22→	if err := validation.ValidateSessionID(sessionID); err != nil {
23→		return fmt.Errorf("invalid session ID: %w", err)
24→	}
25→
26→	if err := os.MkdirAll(s.stateDir, 0o750); err != nil {
27→		return fmt.Errorf("failed to create state directory: %w", err)
28→	}
29→
30→	path := s.fileEditsPath(sessionID)
31→	f, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600)
32→	if err != nil {
33→		return fmt.Errorf("failed to open file edits log: %w", err)
34→	}
35→	defer f.Close()
36→
37→	data, err := json.Marshal(edit)
38→	if err != nil {
39→		return fmt.Errorf("failed to marshal file edit: %w", err)
40→	}
41→	data = append(data, '\n')
42→
43→	if _, err := f.Write(data); err != nil {
44→		return fmt.Errorf("failed to write file edit: %w", err)
45→	}
46→	return nil
47→}
