49→// ReadFileEdits reads all FileEdit records from the session's edit log.
50→// Returns empty slice (not error) if the log doesn't exist.
51→func (s *StateStore) ReadFileEdits(sessionID string) ([]agent.FileEdit, error) {
52→	if err := validation.ValidateSessionID(sessionID); err != nil {
53→		return nil, fmt.Errorf("invalid session ID: %w", err)
54→	}
55→
56→	path := s.fileEditsPath(sessionID)
57→	f, err := os.Open(path)
58→	if os.IsNotExist(err) {
59→		return nil, nil
60→	}
61→	if err != nil {
62→		return nil, fmt.Errorf("failed to open file edits log: %w", err)
63→	}
64→	defer f.Close()
65→
66→	var edits []agent.FileEdit
67→	scanner := bufio.NewScanner(f)
68→	for scanner.Scan() {
69→		line := scanner.Bytes()
70→		if len(line) == 0 {
71→			continue
72→		}
73→		var edit agent.FileEdit
74→		if err := json.Unmarshal(line, &edit); err != nil {
75→			continue // Skip malformed lines
76→		}
77→		edits = append(edits, edit)
78→	}
79→	if err := scanner.Err(); err != nil {
80→		return edits, fmt.Errorf("failed to read file edits log: %w", err)
81→	}
82→	return edits, nil
83→}
