 95→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 96→				return 0, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
 97→			}
 98→		}
 99→		if permRaw, ok := rawSettings["permissions"]; ok {
100→			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
101→				return 0, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
102→			}
103→		}
104→	} else {
105→		rawSettings = make(map[string]json.RawMessage)
106→	}
107→
108→	if rawHooks == nil {
109→		rawHooks = make(map[string]json.RawMessage)
110→	}
111→	if rawPermissions == nil {
112→		rawPermissions = make(map[string]json.RawMessage)
113→	}
114→
115→	// Parse only the hook types we need to modify
116→	var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
117→	parseHookType(rawHooks, "SessionStart", &sessionStart)
118→	parseHookType(rawHooks, "SessionEnd", &sessionEnd)
119→	parseHookType(rawHooks, "Stop", &stop)
120→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
121→	parseHookType(rawHooks, "PreToolUse", &preToolUse)
122→	parseHookType(rawHooks, "PostToolUse", &postToolUse)
123→
124→	// If force is true, remove all existing Entire hooks first
125→	if force {
126→		sessionStart = removeEntireHooks(sessionStart)
127→		sessionEnd = removeEntireHooks(sessionEnd)
128→		stop = removeEntireHooks(stop)
129→		userPromptSubmit = removeEntireHooks(userPromptSubmit)
130→		preToolUse = removeEntireHooksFromMatchers(preToolUse)
131→		postToolUse = removeEntireHooksFromMatchers(postToolUse)
132→	}
133→
134→	// Define hook commands
135→	var sessionStartCmd, sessionEndCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, postTodoCmd, postFileEditCmd string
136→	if localDev {
137→		sessionStartCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code session-start"
138→		sessionEndCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code session-end"
139→		stopCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop"
140→		userPromptSubmitCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code user-prompt-submit"
141→		preTaskCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code pre-task"
142→		postTaskCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-task"
143→		postTodoCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-todo"
144→		postFileEditCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-file-edit"
145→	} else {
146→		sessionStartCmd = "entire hooks claude-code session-start"
147→		sessionEndCmd = "entire hooks claude-code session-end"
148→		stopCmd = "entire hooks claude-code stop"
149→		userPromptSubmitCmd = "entire hooks claude-code user-prompt-submit"
150→		preTaskCmd = "entire hooks claude-code pre-task"
151→		postTaskCmd = "entire hooks claude-code post-task"
152→		postTodoCmd = "entire hooks claude-code post-todo"
153→		postFileEditCmd = "entire hooks claude-code post-file-edit"
154→	}
155→
156→	count := 0
157→
158→	// Add hooks if they don't exist
159→	if !hookCommandExists(sessionStart, sessionStartCmd) {
160→		sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
161→		count++
162→	}
163→	if !hookCommandExists(sessionEnd, sessionEndCmd) {
164→		sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
165→		count++
166→	}
167→	if !hookCommandExists(stop, stopCmd) {
168→		stop = addHookToMatcher(stop, "", stopCmd)
169→		count++
170→	}
171→	if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
172→		userPromptSubmit = addHookToMatcher(userPromptSubmit, "", userPromptSubmitCmd)
173→		count++
174→	}
175→	if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
176→		preToolUse = addHookToMatcher(preToolUse, "Task", preTaskCmd)
177→		count++
178→	}
179→	if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
180→		postToolUse = addHookToMatcher(postToolUse, "Task", postTaskCmd)
181→		count++
182→	}
183→	if !hookCommandExistsWithMatcher(postToolUse, "TodoWrite", postTodoCmd) {
184→		postToolUse = addHookToMatcher(postToolUse, "TodoWrite", postTodoCmd)
185→		count++
186→	}
187→	if !hookCommandExistsWithMatcher(postToolUse, "Write", postFileEditCmd) {
188→		postToolUse = addHookToMatcher(postToolUse, "Write", postFileEditCmd)
189→		count++
190→	}
191→	if !hookCommandExistsWithMatcher(postToolUse, "Edit", postFileEditCmd) {
192→		postToolUse = addHookToMatcher(postToolUse, "Edit", postFileEditCmd)
193→		count++
194→	}
195→
196→	// Add permissions.deny rule if not present
197→	permissionsChanged := false
198→	var denyRules []string
199→	if denyRaw, ok := rawPermissions["deny"]; ok {
200→		if err := json.Unmarshal(denyRaw, &denyRules); err != nil {
201→			return 0, fmt.Errorf("failed to parse permissions.deny in settings.json: %w", err)
202→		}
203→	}
204→	if !slices.Contains(denyRules, metadataDenyRule) {
205→		denyRules = append(denyRules, metadataDenyRule)
206→		denyJSON, err := json.Marshal(denyRules)
207→		if err != nil {
208→			return 0, fmt.Errorf("failed to marshal permissions.deny: %w", err)
209→		}
210→		rawPermissions["deny"] = denyJSON
211→		permissionsChanged = true
212→	}
213→
214→	if count == 0 && !permissionsChanged {
215→		return 0, nil // All hooks and permissions already installed
216→	}
217→
218→	// Marshal modified hook types back to rawHooks
219→	marshalHookType(rawHooks, "SessionStart", sessionStart)
220→	marshalHookType(rawHooks, "SessionEnd", sessionEnd)
221→	marshalHookType(rawHooks, "Stop", stop)
222→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
223→	marshalHookType(rawHooks, "PreToolUse", preToolUse)
224→	marshalHookType(rawHooks, "PostToolUse", postToolUse)
225→
226→	// Marshal hooks and update raw settings
227→	hooksJSON, err := json.Marshal(rawHooks)
228→	if err != nil {
229→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
230→	}
231→	rawSettings["hooks"] = hooksJSON
232→
233→	// Marshal permissions and update raw settings
234→	permJSON, err := json.Marshal(rawPermissions)
235→	if err != nil {
236→		return 0, fmt.Errorf("failed to marshal permissions: %w", err)
237→	}
238→	rawSettings["permissions"] = permJSON
239→
240→	// Write back to file
241→	if err := os.MkdirAll(filepath.Dir(settingsPath), 0o750); err != nil {
242→		return 0, fmt.Errorf("failed to create .claude directory: %w", err)
243→	}
244→
245→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
246→	if err != nil {
247→		return 0, fmt.Errorf("failed to marshal settings: %w", err)
248→	}
249→
250→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
251→		return 0, fmt.Errorf("failed to write settings.json: %w", err)
252→	}
253→
254→	return count, nil
255→}
