257→// parseHookType parses a specific hook type from rawHooks into the target slice.
258→// Silently ignores parse errors (leaves target unchanged).
259→func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]ClaudeHookMatcher) {
260→	if data, ok := rawHooks[hookType]; ok {
261→		//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
262→		json.Unmarshal(data, target)
263→	}
264→}
