266→// marshalHookType marshals a hook type back to rawHooks.
267→// If the slice is empty, removes the key from rawHooks.
268→func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, matchers []ClaudeHookMatcher) {
269→	if len(matchers) == 0 {
270→		delete(rawHooks, hookType)
271→		return
272→	}
273→	data, err := json.Marshal(matchers)
274→	if err != nil {
275→		return // Silently ignore marshal errors (shouldn't happen)
276→	}
277→	rawHooks[hookType] = data
278→}
