280→// UninstallHooks removes Entire hooks from Claude Code settings.
281→func (c *ClaudeCodeAgent) UninstallHooks(ctx context.Context) error {
282→	// Use repo root to find .claude directory when run from a subdirectory
283→	repoRoot, err := paths.WorktreeRoot(ctx)
284→	if err != nil {
285→		repoRoot = "." // Fallback to CWD if not in a git repo
286→	}
287→	settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
288→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
289→	if err != nil {
290→		return nil //nolint:nilerr // No settings file means nothing to uninstall
291→	}
292→
293→	var rawSettings map[string]json.RawMessage
294→	if err := json.Unmarshal(data, &rawSettings); err != nil {
295→		return fmt.Errorf("failed to parse settings.json: %w", err)
296→	}
297→
298→	// rawHooks preserves unknown hook types (e.g., "Notification", "SubagentStop")
299→	var rawHooks map[string]json.RawMessage
300→	if hooksRaw, ok := rawSettings["hooks"]; ok {
301→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
302→			return fmt.Errorf("failed to parse hooks: %w", err)
303→		}
304→	}
305→	if rawHooks == nil {
306→		rawHooks = make(map[string]json.RawMessage)
307→	}
308→
309→	// Parse only the hook types we need to modify
310→	var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
311→	parseHookType(rawHooks, "SessionStart", &sessionStart)
312→	parseHookType(rawHooks, "SessionEnd", &sessionEnd)
313→	parseHookType(rawHooks, "Stop", &stop)
314→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
315→	parseHookType(rawHooks, "PreToolUse", &preToolUse)
316→	parseHookType(rawHooks, "PostToolUse", &postToolUse)
317→
318→	// Remove Entire hooks from all hook types
319→	sessionStart = removeEntireHooks(sessionStart)
320→	sessionEnd = removeEntireHooks(sessionEnd)
321→	stop = removeEntireHooks(stop)
322→	userPromptSubmit = removeEntireHooks(userPromptSubmit)
323→	preToolUse = removeEntireHooksFromMatchers(preToolUse)
324→	postToolUse = removeEntireHooksFromMatchers(postToolUse)
325→
326→	// Marshal modified hook types back to rawHooks
327→	marshalHookType(rawHooks, "SessionStart", sessionStart)
328→	marshalHookType(rawHooks, "SessionEnd", sessionEnd)
329→	marshalHookType(rawHooks, "Stop", stop)
330→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
331→	marshalHookType(rawHooks, "PreToolUse", preToolUse)
332→	marshalHookType(rawHooks, "PostToolUse", postToolUse)
333→
334→	// Also remove the metadata deny rule from permissions
335→	var rawPermissions map[string]json.RawMessage
336→	if permRaw, ok := rawSettings["permissions"]; ok {
337→		if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
338→			// If parsing fails, just skip permissions cleanup
339→			rawPermissions = nil
340→		}
341→	}
342→
343→	if rawPermissions != nil {
344→		if denyRaw, ok := rawPermissions["deny"]; ok {
345→			var denyRules []string
346→			if err := json.Unmarshal(denyRaw, &denyRules); err == nil {
347→				// Filter out the metadata deny rule
348→				filteredRules := make([]string, 0, len(denyRules))
349→				for _, rule := range denyRules {
350→					if rule != metadataDenyRule {
351→						filteredRules = append(filteredRules, rule)
352→					}
353→				}
354→				if len(filteredRules) > 0 {
355→					denyJSON, err := json.Marshal(filteredRules)
356→					if err == nil {
357→						rawPermissions["deny"] = denyJSON
358→					}
359→				} else {
360→					// Remove empty deny array
361→					delete(rawPermissions, "deny")
362→				}
363→			}
364→		}
365→
366→		// If permissions is empty, remove it entirely
367→		if len(rawPermissions) > 0 {
368→			permJSON, err := json.Marshal(rawPermissions)
369→			if err == nil {
370→				rawSettings["permissions"] = permJSON
371→			}
372→		} else {
373→			delete(rawSettings, "permissions")
374→		}
375→	}
376→
377→	// Marshal hooks back (preserving unknown hook types)
378→	if len(rawHooks) > 0 {
379→		hooksJSON, err := json.Marshal(rawHooks)
380→		if err != nil {
381→			return fmt.Errorf("failed to marshal hooks: %w", err)
382→		}
383→		rawSettings["hooks"] = hooksJSON
384→	} else {
385→		delete(rawSettings, "hooks")
386→	}
387→
388→	// Write back
389→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
390→	if err != nil {
391→		return fmt.Errorf("failed to marshal settings: %w", err)
392→	}
393→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
394→		return fmt.Errorf("failed to write settings.json: %w", err)
395→	}
396→	return nil
397→}
