399→// AreHooksInstalled checks if Entire hooks are installed.
400→func (c *ClaudeCodeAgent) AreHooksInstalled(ctx context.Context) bool {
401→	// Use repo root to find .claude directory when run from a subdirectory
402→	repoRoot, err := paths.WorktreeRoot(ctx)
403→	if err != nil {
404→		repoRoot = "." // Fallback to CWD if not in a git repo
405→	}
406→	settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
407→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
408→	if err != nil {
409→		return false
410→	}
411→
412→	var settings ClaudeSettings
413→	if err := json.Unmarshal(data, &settings); err != nil {
414→		return false
415→	}
416→
417→	// Check for at least one of our hooks (new or old format)
418→	return hookCommandExists(settings.Hooks.Stop, "entire hooks claude-code stop") ||
419→		hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop") ||
420→		// Backwards compatibility: check for old hook formats
421→		hookCommandExists(settings.Hooks.Stop, "entire hooks claudecode stop") ||
422→		hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claudecode stop") ||
423→		hookCommandExists(settings.Hooks.Stop, "entire rewind claude-hook --stop") ||
424→		hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go rewind claude-hook --stop")
425→}
