427→// Helper functions for hook management
428→
429→func hookCommandExists(matchers []ClaudeHookMatcher, command string) bool {
430→	for _, matcher := range matchers {
431→		for _, hook := range matcher.Hooks {
432→			if hook.Command == command {
433→				return true
434→			}
435→		}
436→	}
437→	return false
438→}
439→
440→func hookCommandExistsWithMatcher(matchers []ClaudeHookMatcher, matcherName, command string) bool {
441→	for _, matcher := range matchers {
442→		if matcher.Matcher == matcherName {
443→			for _, hook := range matcher.Hooks {
444→				if hook.Command == command {
445→					return true
446→				}
447→			}
448→		}
449→	}
450→	return false
451→}
452→
453→func addHookToMatcher(matchers []ClaudeHookMatcher, matcherName, command string) []ClaudeHookMatcher {
454→	entry := ClaudeHookEntry{
455→		Type:    "command",
456→		Command: command,
457→	}
458→
459→	// If no matcher name, add to a matcher with empty string
460→	if matcherName == "" {
461→		for i, matcher := range matchers {
462→			if matcher.Matcher == "" {
463→				matchers[i].Hooks = append(matchers[i].Hooks, entry)
464→				return matchers
465→			}
466→		}
467→		return append(matchers, ClaudeHookMatcher{
468→			Matcher: "",
469→			Hooks:   []ClaudeHookEntry{entry},
470→		})
471→	}
472→
473→	// Find or create matcher with the given name
474→	for i, matcher := range matchers {
475→		if matcher.Matcher == matcherName {
476→			matchers[i].Hooks = append(matchers[i].Hooks, entry)
477→			return matchers
478→		}
479→	}
480→
481→	return append(matchers, ClaudeHookMatcher{
482→		Matcher: matcherName,
483→		Hooks:   []ClaudeHookEntry{entry},
484→	})
485→}
