487→// isEntireHook checks if a command is an Entire hook (old or new format)
488→func isEntireHook(command string) bool {
489→	for _, prefix := range entireHookPrefixes {
490→		if strings.HasPrefix(command, prefix) {
491→			return true
492→		}
493→	}
494→	return false
495→}
496→
497→// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
498→func removeEntireHooks(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
499→	result := make([]ClaudeHookMatcher, 0, len(matchers))
500→	for _, matcher := range matchers {
501→		filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
502→		for _, hook := range matcher.Hooks {
503→			if !isEntireHook(hook.Command) {
504→				filteredHooks = append(filteredHooks, hook)
505→			}
506→		}
507→		// Only keep the matcher if it has hooks remaining
508→		if len(filteredHooks) > 0 {
509→			matcher.Hooks = filteredHooks
510→			result = append(result, matcher)
511→		}
512→	}
513→	return result
514→}
515→
516→// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
517→// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Task", "TodoWrite")
518→func removeEntireHooksFromMatchers(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
519→	// Same logic as removeEntireHooks - both work on the same structure
520→	return removeEntireHooks(matchers)
521→}
